{"explanation":"Use the sliders to change all four parameters and watch the wave respond. |A| controls amplitude (negative A flips the wave), B controls the period 2π/B, C shifts it horizontally, and D shifts it vertically. The gray line shows the midline y = D, and the yellow point marks (C, D).","manimCode":"const heading = new Text({ text: 'Shape a sine wave', color: WHITE, fontSize: 32 });
heading.moveTo([-1, 3.15, 0]);
const formula = new MathTex({ latex: 'y=A\\sin\\bigl(B(x-C)\\bigr)+D' });
await formula.waitForRender();
formula.moveTo([-1, 2.5, 0]);
formula.scale(0.85);

const ax = new Axes({
  xRange: [-2 * Math.PI, 2 * Math.PI, Math.PI / 2],
  yRange: [-5.5, 5.5, 1],
  xLength: 8,
  yLength: 4.4,
  tips: false
});
ax.moveTo([-1, -0.25, 0]);

let amplitude = 1;
let frequency = 1;
let horizontal = 0;
let vertical = 0;
const waveValue = x => amplitude * Math.sin(frequency * (x - horizontal)) + vertical;
let wave = ax.plot(waveValue, { color: BLUE, numSamples: 650 });
wave.setStrokeWidth(3);
let midline = ax.plot(() => vertical, { color: GRAY });
midline.setStrokeWidth(1.5);
const anchor = new Dot({ point: ax.c2p(horizontal, vertical), color: YELLOW });

let readout;
function refreshReadout() {
  if (readout) scene.remove(readout);
  readout = new Text({
    text: 'Amplitude: ' + Math.abs(amplitude).toFixed(2) + '     Period: ' + (2 * Math.PI / frequency).toFixed(2) + '\nHorizontal shift: ' + horizontal.toFixed(2) + '     Midline: ' + vertical.toFixed(2),
    color: WHITE,
    fontSize: 20
  });
  readout.moveTo([-1, -3.05, 0]);
  scene.add(readout);
}

function refreshWave() {
  scene.remove(wave, midline);
  midline = ax.plot(() => vertical, { color: GRAY });
  midline.setStrokeWidth(1.5);
  wave = ax.plot(waveValue, { color: BLUE, numSamples: 650 });
  wave.setStrokeWidth(3);
  scene.add(midline, wave);
  anchor.moveTo(ax.c2p(horizontal, vertical));
  scene.remove(anchor);
  scene.add(anchor);
  refreshReadout();
}

scene.add(heading, formula, ax, midline);
await scene.play(new Create(wave));
scene.add(anchor);
refreshReadout();
makeHoverable(anchor, scene, { hoverScale: 1.5, hoverColor: ORANGE });

const controls = new Controls(scene, { position: 'top-right', theme: 'dark', width: 240 });
controls.addSlider({
  label: 'A — amplitude / flip', min: -3, max: 3, value: 1, step: 0.05,
  onChange: value => { amplitude = value; refreshWave(); }
});
controls.addSlider({
  label: 'B — frequency', min: 0.25, max: 3, value: 1, step: 0.05,
  onChange: value => { frequency = value; refreshWave(); }
});
controls.addSlider({
  label: 'C — horizontal shift', min: -Math.PI, max: Math.PI, value: 0, step: 0.05,
  onChange: value => { horizontal = value; refreshWave(); }
});
controls.addSlider({
  label: 'D — vertical shift', min: -2, max: 2, value: 0, step: 0.05,
  onChange: value => { vertical = value; refreshWave(); }
